import{_ as t,c as a,ae as o,o as i}from"./chunks/framework.Buicxtqr.js";const u=JSON.parse('{"title":"Getting Started with BuddyGenAI","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),n={name:"getting-started.md"};function l(h,e,d,r,s,c){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="getting-started-with-buddygenai" tabindex="-1">Getting Started with BuddyGenAI <a class="header-anchor" href="#getting-started-with-buddygenai" aria-label="Permalink to &quot;Getting Started with BuddyGenAI&quot;">​</a></h1><p>This guide should walk you through the process of to set up BuddyGenAI to be able to chat, generate images and speech, and be able to speak your messages using a microphone.</p><p>With BuddyGenAI, you have the ability to pick and choose which AI models you want to use which will affect the performance and quality of the application.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>First, your machine should have the following requirements:</p><ul><li>Windows 10 or later</li><li>Install <a href="https://aka.ms/vs/17/release/vc_redist.x64.exe" target="_blank" rel="noreferrer">Microsoft Visual C++ Redistributable x64</a></li><li>NVIDIA GPU with 6GB+ of VRAM (10-12GB is recommended) <ul><li>RTX 20XX or newer is recommended</li><li>More VRAM allows for using more / better AI models</li><li>Install the latest NVIDIA drivers and <a href="https://developer.nvidia.com/cuda-downloads" target="_blank" rel="noreferrer">CUDA Toolkit</a></li></ul></li><li>25GB of disk space (rough estimate)</li></ul><h2 id="installation-and-setup" tabindex="-1">Installation and Setup <a class="header-anchor" href="#installation-and-setup" aria-label="Permalink to &quot;Installation and Setup&quot;">​</a></h2><ol><li><p>Download and install the latest version of BuddyGenAI from the <a href="https://github.com/parsehex/BuddyGenAI/releases" target="_blank" rel="noreferrer">releases page</a>.</p></li><li><p>Choose and download the AI models you want to use -- you can use <a href="https://github.com/parsehex/BuddyGenAI/blob/main/docs/getting-models.md" target="_blank" rel="noreferrer">this page</a> for model recommendations and download links.</p></li><li><p>Open BuddyGenAI and click the button to Import Models and select the model files you downloaded. Once done, click Continue and wait for the chat model to load before you see the next page.</p><ul><li>If the model keeps loading, restarting the app may help. If that doesn&#39;t work, you may be missing Microsoft Visual C++ Redistributable x64 or CUDA Toolkit (see Compatibility section above).</li></ul></li><li><p>The next page will ask for your name and then you&#39;ll provide info to make your first buddy. Give them a name and keywords that describe how they behave.</p></li><li><p>After you click Create Buddy, you&#39;ll be able to choose your buddy&#39;s appearance and generate a profile picture for them.</p><ul><li>You can only choose 1 profile picture but all generated pictures can be seen by going to the buddy&#39;s Edit page.</li></ul></li></ol><h2 id="chatting" tabindex="-1">Chatting <a class="header-anchor" href="#chatting" aria-label="Permalink to &quot;Chatting&quot;">​</a></h2><p>After creating a buddy, you&#39;ll be taken to a new chat with them. To create a new chat, go to the Chat tab, select a buddy from the dropdown labelled <code>Start a chat with...</code> and click the <code>+</code> button to start a chat.</p><h3 id="enable-ai-sent-chat-images" tabindex="-1">Enable (AI-sent) Chat Images <a class="header-anchor" href="#enable-ai-sent-chat-images" aria-label="Permalink to &quot;Enable (AI-sent) Chat Images&quot;">​</a></h3><p>Chat images are disabled by default. To enable them, go to the Settings tab -&gt; <code>Image AI Options</code>. Click &quot;Enable chat images&quot; and optionally change the quality dropdown under it, which will affect the quality and speed of the images generated.</p><p>With the option enabled, any AI in the app may generate and send images based on the chat&#39;s context.</p><h3 id="text-to-speech" tabindex="-1">Text-to-Speech <a class="header-anchor" href="#text-to-speech" aria-label="Permalink to &quot;Text-to-Speech&quot;">​</a></h3><p>If you&#39;ve imported TTS voice(s) then you can click the speaker icon on AI messages to have them spoken out loud. You can set buddies to have a specific voice by going to the buddy&#39;s Edit page.</p><p>You can have message auto-speak by going to the Settings tab -&gt; <code>Text-to-Speech Options</code> and enabling the option &quot;Auto Read Chat&quot;.</p><h3 id="microphone-input-speech-to-text" tabindex="-1">Microphone Input / Speech-to-Text <a class="header-anchor" href="#microphone-input-speech-to-text" aria-label="Permalink to &quot;Microphone Input / Speech-to-Text&quot;">​</a></h3><p>If you&#39;ve imported an STT model, you can click the microphone icon in the chat input, speak your message and click the microphone icon again to have your speech converted to text.</p><p>You can automatically send messages after converting speech to text by going to the Settings tab -&gt; <code>Speech-to-Text Options</code> and enabling the option &quot;Auto Send STT&quot;. Now, after you click to stop recording &amp; transcription is finished, the message will be sent without needing to click the Send button.</p><h3 id="changing-models" tabindex="-1">Changing Models <a class="header-anchor" href="#changing-models" aria-label="Permalink to &quot;Changing Models&quot;">​</a></h3><p>You may change and import AI models by going to the Settings tab.</p><p>Note that if you change the chat model then you&#39;ll need to restart the app or use the in-app control to restart the chat model (through the Chat tab -&gt; click &quot;Chat Online&quot;).</p>',22)]))}const g=t(n,[["render",l]]);export{u as __pageData,g as default};
